'use strict';

var bernoulli = require( '@stdlib/random/array/bernoulli' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var zeros = require( '@stdlib/array/base/zeros' );
var gwhereRows = require( './../lib' );

// Matrix dimensions:
var M = 3;
var N = 4;

var condition = bernoulli( M, 0.5, {
	'dtype': 'generic'
});
console.log( condition );

var A = discreteUniform( M*N, 0, 100, {
	'dtype': 'generic'
});
console.log( A );

var B = discreteUniform( M*N, -100, 0, {
	'dtype': 'generic'
});
console.log( B );

var out = zeros( M*N );
console.log( out );

// For each row, if condition is truthy, copy row from A to output; otherwise copy row from B:
gwhereRows( 'row-major', 'no-transpose', 'no-transpose', M, N, condition, 1, A, N, B, N, out, N );
console.log( out );
